```java
import java.util.*;
import java.util.function.*;

public class MethodReferenceDemo {
    public static void main(String[] args) {
        // Rodzaj 1: ClassName::staticMethod
        Function<String, Integer> parse = Integer::parseInt;
        System.out.println(parse.apply("42")); // 42

        BinaryOperator<Integer> max = Math::max;
        System.out.println(max.apply(3, 7)); // 7

        // Rodzaj 2: particularObject::instanceMethod (bound)
        List<String> names = new ArrayList<>();
        Consumer<String> addToNames = names::add;
        addToNames.accept("Ala");
        System.out.println(names); // [Ala]

        String greeting = "hej";
        Supplier<String> shout = greeting::toUpperCase;
        System.out.println(shout.get()); // HEJ

        // Rodzaj 3: ClassName::instanceMethod (unbound)
        Function<String, String> toUpper = String::toUpperCase;
        System.out.println(toUpper.apply("cichy")); // CICHY

        BiFunction<String, String, Boolean> startsWith = String::startsWith;
        System.out.println(startsWith.apply("JavaQuest", "Java")); // true

        // Rodzaj 4: ClassName::new
        Supplier<List<String>> listFactory = ArrayList::new;
        List<String> fresh = listFactory.get();
        System.out.println(fresh.isEmpty()); // true

        IntFunction<String[]> arrayFactory = String[]::new;
        String[] arr = arrayFactory.apply(3);
        System.out.println(arr.length); // 3
    }
}
