record Product(String name, double price) {
    String describe() { return name + ": " + price + " zl"; }
}

interface Mapper<T, R> { R map(T t); }

class ProductRepository {
    private final List<Product> produkty = new ArrayList<>();
    private final BiFunction<String, Double, Product> factory = Product::new;
    private final Mapper<Product, String> opisMapper = Product::describe;

    void dodaj(String name, double price) {
        produkty.add(factory.apply(name, price));
    }

    List<String> opisyWszystkich() {
        List<String> opisy = new ArrayList<>();
        for (Product p : produkty) opisy.add(opisMapper.map(p));
        return opisy;
    }
}

ProductRepository repo = new ProductRepository();
repo.dodaj("Ksiazka", 39.99);
repo.dodaj("Dlugopis", 3.50);
System.out.println(repo.opisyWszystkich());
